package com.growworld.controller;
import com.growworld.dto.AuthDtos.*; import com.growworld.service.AuthService; import jakarta.servlet.http.HttpServletResponse; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.web.csrf.CsrfToken; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController {private final AuthService service;public AuthController(AuthService s){service=s;} @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) UserResponse register(@Valid @RequestBody RegisterRequest r,HttpServletResponse res){return service.register(r,res);} @PostMapping("/login") UserResponse login(@Valid @RequestBody LoginRequest r,HttpServletResponse res){return service.login(r,res);} @PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) void logout(HttpServletResponse res){service.logout(res);} @GetMapping("/me") UserResponse me(Authentication a){return service.me((UUID)a.getPrincipal());} @GetMapping("/csrf") CsrfToken csrf(CsrfToken token){return token;} }
